{
  "rule_name": "rule_common_stock_listing_narrative",
  "file": "/mnt/data/LSF/rules/financebench/agentic_rule_full_data_gpt54mini/all_docs/q01_what_stock_exchange_is_the_companys_primary_common_stock_lis/rule_common_stock_listing_narrative.py",
  "code": "import re\n\n\n_COMMON_RE = re.compile(r\"\\bcommon\\s+(?:stock|shares)\\b\", re.IGNORECASE)\n_PRIMARY_RE = re.compile(r\"\\b(?:primary\\s+exchange|principal\\s+market)\\b\", re.IGNORECASE)\n_LISTING_RE = re.compile(\n    r\"\\b(?:\"\n    r\"listed\\s+on|\"\n    r\"traded\\s+on|\"\n    r\"currently\\s+listed\\s+on|\"\n    r\"currently\\s+trades\\s+on|\"\n    r\"stock\\s+is\\s+listed\\s+on|\"\n    r\"common\\s+stock\\s+is\\s+listed\\s+on|\"\n    r\"common\\s+stock\\s+is\\s+traded\\s+on|\"\n    r\"principal\\s+market\\s+for\\s+(?:our|the)\\s+common\\s+stock\\s+is|\"\n    r\"our\\s+common\\s+stock\\s+is\\s+listed\\s+on|\"\n    r\"our\\s+common\\s+stock\\s+is\\s+traded\\s+on\"\n    r\")\\b\",\n    re.IGNORECASE,\n)\n_EXCHANGE_RE = re.compile(\n    r\"\\b(?:\"\n    r\"New\\s+York\\s+Stock\\s+Exchange(?:,?\\s+Inc\\.)?|\"\n    r\"NYSE(?:\\s+American|\\s+Arca)?|\"\n    r\"The\\s+Nasdaq\\s+Stock\\s+Market\\s+LLC|\"\n    r\"Nasdaq(?:\\s+Global\\s+Select\\s+Market|\\s+Global\\s+Market|\\s+Capital\\s+Market)?|\"\n    r\"NASDAQ|\"\n    r\"SIX\\s+Swiss\\s+Exchange|\"\n    r\"Chicago\\s+Stock\\s+Exchange|\"\n    r\"London\\s+Stock\\s+Exchange|\"\n    r\"Toronto\\s+Stock\\s+Exchange\"\n    r\")\\b\",\n    re.IGNORECASE,\n)\n\n\ndef rule_common_stock_listing_narrative(doc: dict) -> list[dict]:\n    try:\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").replace(\"\\u00a0\", \" \")).strip()\n\n        def score(text: str) -> int:\n            cleaned = norm(text)\n            if not cleaned:\n                return 0\n            lower = cleaned.lower()\n            if \"preferred stock\" in lower:\n                return 0\n            score_val = 0\n            if _COMMON_RE.search(cleaned):\n                score_val += 2\n            if _LISTING_RE.search(cleaned):\n                score_val += 3\n            if _PRIMARY_RE.search(cleaned):\n                score_val += 2\n            if _EXCHANGE_RE.search(cleaned):\n                score_val += 2\n            if \"notes\" in lower and \"common stock\" not in lower:\n                score_val -= 2\n            return score_val\n\n        items = [item for item in (doc.get(\"paragraphs\") or []) if isinstance(item, dict)]\n        if not items:\n            items = [item for item in (doc.get(\"lines\") or []) if isinstance(item, dict)]\n        if not items:\n            return []\n\n        spans: list[dict] = []\n        seen: set[str] = set()\n\n        def add(src: dict, text: str) -> None:\n            cleaned = norm(text)\n            if not cleaned:\n                return\n            key = cleaned.lower()\n            if key in seen:\n                return\n            seen.add(key)\n            span = {\"text\": cleaned}\n            if src.get(\"page_no\") is not None:\n                span[\"page_no\"] = src.get(\"page_no\")\n            if src.get(\"line_no\") is not None:\n                span[\"line_no\"] = src.get(\"line_no\")\n            if src.get(\"paragraph_no\") is not None:\n                span[\"paragraph_no\"] = src.get(\"paragraph_no\")\n            spans.append(span)\n\n        ranked = []\n        for item in items:\n            text = norm(item.get(\"text\") or \"\")\n            s = score(text)\n            if s > 0:\n                ranked.append((s, item, text))\n\n        ranked.sort(key=lambda x: (-x[0], int(x[1].get(\"page_no\") or 0), int(x[1].get(\"line_no\") or 0), int(x[1].get(\"paragraph_no\") or 0)))\n\n        for _, item, text in ranked[:10]:\n            add(item, text)\n\n        return spans\n    except Exception:\n        return []\n",
